1555	func findTrail(ctx context.Context, client *api.Client, forge, owner, repo string, match func(api.TrailResource) bool) (*api.TrailResource, error) {
1556		// The list endpoint paginates; walk bounded pages so branch/number/id lookups do
1557		// not silently miss older trails beyond the first server-max page.
1558		offset := 0
1559		previousPageSignature := ""
1560		for range trailFindMaxPages {
1561			resp, err := client.Get(ctx, trailsBasePath(forge, owner, repo)+trailListQueryWithOffset(nil, "", trailListServerMaxLimit, offset))
1562			if err != nil {
1563				return nil, fmt.Errorf("list trails: %w", err)
1564			}
1565	
1566			var listResp api.TrailListResponse
1567			decodeErr := func() error {
1568				defer resp.Body.Close()
1569				if err := checkTrailResponse(resp); err != nil {
1570					return err
1571				}
1572				if err := api.DecodeJSON(resp, &listResp); err != nil {
1573					return fmt.Errorf("decode trail list: %w", err)
1574				}
1575				return nil
1576			}()
1577			if decodeErr != nil {
1578				return nil, decodeErr
1579			}
1580	
1581			for i := range listResp.Trails {
1582				if match(listResp.Trails[i]) {
1583					return &listResp.Trails[i], nil
1584				}
1585			}
1586	
1587			pageLen := len(listResp.Trails)
1588			if pageLen == 0 || pageLen < trailListServerMaxLimit {
1589				break
1590			}
1591			if listResp.Total == 0 {
1592				pageSignature := trailListPageSignature(listResp.Trails)
1593				if pageSignature != "" && pageSignature == previousPageSignature {
1594					break
1595				}
1596				previousPageSignature = pageSignature
1597			}
1598			offset += pageLen
1599			if listResp.Total > 0 && offset >= listResp.Total {
1600				break
1601			}
1602		}
1603		return nil, nil //nolint:nilnil // nil, nil means "not found" — callers check both
1604	}
