1673	// slugifyTitle converts a title string into a branch-friendly slug.
1674	// Example: "Add user authentication" -> "add-user-authentication"
1675	func slugifyTitle(title string) string {
1676		s := strings.ToLower(strings.TrimSpace(title))
1677		// Replace spaces and underscores with hyphens
1678		s = strings.NewReplacer(" ", "-", "_", "-").Replace(s)
1679		// Remove anything that's not alphanumeric, hyphen, or slash
1680		var b strings.Builder
1681		prevHyphen := false
1682		for _, r := range s {
1683			if (r >= 'a' && r <= 'z') || (r >= '0' && r <= '9') || r == '/' {
1684				b.WriteRune(r)
1685				prevHyphen = false
1686			} else if r == '-' && !prevHyphen {
1687				b.WriteRune('-')
1688				prevHyphen = true
1689			}
1690		}
1691		return strings.Trim(b.String(), "-")
1692	}
