481	func resolveTrailReviewTarget(ctx context.Context, client *api.Client, selector string) (trailReviewTarget, error) {
482		host, owner, repo, err := resolveTrailRemote(ctx)
483		if err != nil {
484			return trailReviewTarget{}, err
485		}
486	
487		selector = strings.TrimSpace(selector)
488		var found *api.TrailResource
489		if selector != "" {
490			found, err = findTrailBySelector(ctx, client, host, owner, repo, selector)
491			if err != nil {
492				return trailReviewTarget{}, err
493			}
494			if found == nil {
495				return trailReviewTarget{}, fmt.Errorf("no trail %q found in %s/%s/%s (run 'entire trail list --status any')", selector, host, owner, repo)
496			}
497		} else {
498			branch, branchErr := GetCurrentBranch(ctx)
499			if branchErr != nil {
500				return trailReviewTarget{}, fmt.Errorf("%w: no trail selector given and current branch is unknown: %w\nhint: run 'entire trail list --status any' or pass --trail <number|id|branch>", errTrailReviewDefaultTargetNotFound, branchErr)
501			}
502			found, err = findTrailByBranch(ctx, client, host, owner, repo, branch)
503			if err != nil {
504				return trailReviewTarget{}, err
505			}
506			if found == nil {
507				return trailReviewTarget{}, fmt.Errorf("%w: no trail found for current branch %q\nhint: run 'entire trail create', 'entire trail list --status any', or pass --trail <number|id|branch>", errTrailReviewDefaultTargetNotFound, branch)
508			}
509		}
510		if found.ID == "" {
511			return trailReviewTarget{}, errors.New("trail has no id yet")
512		}
513		return trailReviewTarget{Host: host, Owner: owner, Repo: repo, Trail: *found}, nil
514	}
