516	func normalizeTrailReviewListOptions(opts trailReviewListOptions) (trailReviewListOptions, error) {
517		if opts.Limit <= 0 {
518			return opts, errors.New("limit must be greater than 0")
519		}
520		if opts.Offset < 0 {
521			return opts, errors.New("offset must be non-negative")
522		}
523		status, err := normalizeTrailReviewStatusFilter(opts.Status)
524		if err != nil {
525			return opts, err
526		}
527		opts.Status = status
528		severity, err := normalizeCommaSet(opts.Severity, "severity", map[string]bool{
529			trailReviewSeverityHigh: true, trailReviewSeverityMedium: true, trailReviewSeverityLow: true,
530		})
531		if err != nil {
532			return opts, err
533		}
534		opts.Severity = severity
535		if freshness := strings.TrimSpace(opts.Freshness); freshness != "" {
536			switch freshness {
537			case trailReviewFreshnessCurrent, trailReviewFreshnessStale, trailReviewFreshnessAny:
538			default:
539				return opts, fmt.Errorf("invalid freshness filter %q: valid values are current, stale, any", opts.Freshness)
540			}
541			opts.Freshness = freshness
542		}
543		// `--include-dismissed` should do what it says for the common case: when the
544		// caller did not explicitly choose a status, do not keep the default open-only
545		// status filter that would still hide dismissed findings.
546		if opts.IncludeDismissed && !opts.StatusChanged && strings.TrimSpace(opts.Status) == trailReviewStatusOpen {
547			opts.Status = trailReviewStatusAny
548		}
549		return opts, nil
550	}
551	
552	func normalizeTrailReviewStatusFilter(filter string) (string, error) {
553		filter = strings.TrimSpace(filter)
554		if filter == "" || filter == trailReviewStatusAny {
555			return filter, nil
556		}
557		return normalizeCommaSet(filter, "status", map[string]bool{
558			trailReviewStatusOpen: true, trailReviewStatusResolved: true, trailReviewStatusDismissed: true,
559		})
560	}
561	
562	func normalizeCommaSet(filter, name string, valid map[string]bool) (string, error) {
563		filter = strings.TrimSpace(filter)
564		if filter == "" {
565			return "", nil
566		}
567		parts := strings.Split(filter, ",")
568		out := make([]string, 0, len(parts))
569		for _, part := range parts {
570			value := strings.TrimSpace(part)
571			if value == "" {
572				return "", fmt.Errorf("invalid %s filter %q: empty value", name, filter)
573			}
574			if !valid[value] {
575				vals := make([]string, 0, len(valid))
576				for v := range valid {
577					vals = append(vals, v)
578				}
579				sort.Strings(vals)
580				return "", fmt.Errorf("invalid %s %q: valid values are %s", name, value, strings.Join(vals, ", "))
581			}
582			out = append(out, value)
583		}
584		return strings.Join(out, ","), nil
585	}
