636	func trailReviewCommentsPath(trailID string, opts trailReviewListOptions) string {
637		q := url.Values{}
638		if opts.Status != "" && opts.Status != trailReviewStatusAny {
639			q.Set("status", opts.Status)
640		}
641		if opts.Severity != "" {
642			q.Set("severity", opts.Severity)
643		}
644		// Unlike status=any (which the API treats as no status filter), stale=any is
645		// semantically significant: omitting stale defaults to current-only server-side.
646		if opts.Freshness != "" {
647			q.Set("stale", opts.Freshness)
648		}
649		if opts.IncludeDismissed {
650			q.Set("include_dismissed", "true")
651		}
652		if opts.Limit > 0 {
653			q.Set("limit", strconv.Itoa(opts.Limit))
654		}
655		if opts.Offset > 0 {
656			q.Set("offset", strconv.Itoa(opts.Offset))
657		}
658		path := trailReviewListCommentsPath(trailID)
659		if encoded := q.Encode(); encoded != "" {
