724	func buildTrailReviewCommentInput(opts trailReviewCommentAddOptions) (api.TrailReviewCommentInput, error) {
725		body := strings.TrimSpace(opts.Body)
726		if body == "" {
727			return api.TrailReviewCommentInput{}, errors.New("finding body is required (pass --body)")
728		}
729		severity := strings.ToLower(strings.TrimSpace(opts.Severity))
730		if severity != "" {
731			switch severity {
732			case trailReviewSeverityHigh, trailReviewSeverityMedium, trailReviewSeverityLow:
733			default:
734				return api.TrailReviewCommentInput{}, fmt.Errorf("invalid severity %q: valid values are high, medium, low", opts.Severity)
735			}
736		}
737		confidence, hasConfidence, err := buildTrailReviewCommentConfidence(opts.Confidence)
738		if err != nil {
739			return api.TrailReviewCommentInput{}, err
740		}
741		loc, err := buildTrailReviewCommentLocation(opts)
742		if err != nil {
743			return api.TrailReviewCommentInput{}, err
744		}
745		// client_id is the API's idempotency key and is now required. Honour an
746		// explicit --client-id when given, otherwise generate a unique one so a
747		// retried add doesn't create duplicate findings within the same key.
748		clientID := strings.TrimSpace(opts.ClientID)
749		if clientID == "" {
750			clientID = generateTrailReviewClientID()
751		}
752		input := api.TrailReviewCommentInput{
753			ClientID: clientID,
754			Body:     stringPtr(body),
755			Severity: optionalStringPtr(severity),
756			Location: loc,
757		}
758		if hasConfidence {
759			input.Confidence = &confidence
760		}
761		if patch := strings.TrimSpace(opts.Patch); patch != "" {
762			input.SuggestedChange = &api.TrailReviewSuggestedChangeCreateRequest{
763				ChangeType:  "unified_diff",
764				Patch:       stringPtr(patch),
765				Instruction: optionalStringPtr(strings.TrimSpace(opts.Instruction)),
766			}
767		} else if instruction := strings.TrimSpace(opts.Instruction); instruction != "" {
768			input.SuggestedChange = &api.TrailReviewSuggestedChangeCreateRequest{
769				ChangeType:  "manual_instruction",
770				Instruction: stringPtr(instruction),
771			}
772		}
773		return input, nil
774	}
