817		}
818		loc.Granularity = "file"
819		loc.FilePath = stringPtr(filePath)
820		if line > 0 {
821			loc.Granularity = "line"
822			loc.StartLine = &line
823			if opts.EndLine > 0 {
824				loc.EndLine = &opts.EndLine
825				if opts.EndLine != line {
826					loc.Granularity = "range"
827				}
828			}
829		}
830		return loc, nil
