833	// createTrailReviewFinding posts a single finding through the current API flow:
834	// start a review session, then submit a one-item comment batch under it. It
835	// returns the created (or already-existing) finding.
836	func createTrailReviewFinding(ctx context.Context, client *api.Client, trailID string, input api.TrailReviewCommentInput) (api.TrailReviewComment, error) {
837		review, err := startTrailReview(ctx, client, trailID)
838		if err != nil {
839			return api.TrailReviewComment{}, err
840		}
841		resp, err := client.Post(ctx, trailReviewBatchCommentsPath(trailID, review.ReviewID), api.TrailReviewCommentBatchRequest{
842			Comments: []api.TrailReviewCommentInput{input},
843		})
844		if err != nil {
845			return api.TrailReviewComment{}, fmt.Errorf("create finding: %w", err)
846		}
847		defer resp.Body.Close()
848		if err := checkTrailResponse(resp); err != nil {
849			return api.TrailReviewComment{}, err
850		}
851		var batch api.TrailReviewCommentBatchResponse
852		if err := api.DecodeJSON(resp, &batch); err != nil {
853			return api.TrailReviewComment{}, fmt.Errorf("decode finding batch response: %w", err)
854		}
855		if len(batch.Results) == 0 {
856			return api.TrailReviewComment{}, errors.New("create finding: server returned no results")
857		}
858		result := batch.Results[0]
859		if result.Status == trailReviewBatchResultError {
860			if result.Error != nil {
861				return api.TrailReviewComment{}, fmt.Errorf("create finding: %s: %s", result.Error.Code, result.Error.Message)
862			}
863			return api.TrailReviewComment{}, errors.New("create finding: server reported an error")
864		}
865		if result.Comment == nil {
866			return api.TrailReviewComment{}, errors.New("create finding: server did not return the finding")
867		}
868		return *result.Comment, nil
869	}
