872	// so the server resolves the code version (base/head) from the trail itself.
873	// The API rejects a lone head_sha — base_sha and head_sha must be supplied
874	// together or not at all — and computing a correct base SHA client-side is out
875	// of scope for a single-finding add, so neither is sent.
876	func startTrailReview(ctx context.Context, client *api.Client, trailID string) (api.TrailReviewStartResponse, error) {
877		resp, err := client.Post(ctx, trailReviewStartPath(trailID), api.TrailReviewStartRequest{})
