879			return api.TrailReviewStartResponse{}, fmt.Errorf("start review: %w", err)
880		}
881		defer resp.Body.Close()
882		if err := checkTrailResponse(resp); err != nil {
883			return api.TrailReviewStartResponse{}, err
884		}
885		var out api.TrailReviewStartResponse
886		if err := api.DecodeJSON(resp, &out); err != nil {
887			return api.TrailReviewStartResponse{}, fmt.Errorf("decode review: %w", err)
888		}
889		if out.ReviewID == "" {
890			return api.TrailReviewStartResponse{}, errors.New("start review: server returned an empty review id")
891		}
892		return out, nil
893	}
