907	func resolveTrailReviewComment(ctx context.Context, client *api.Client, trailID, commentID string) (api.TrailReviewComment, error) {
908		opts := trailReviewListOptions{
909			Status:           trailReviewStatusAny,
910			Freshness:        trailReviewFreshnessAny,
911			IncludeDismissed: true,
912			Limit:            defaultTrailReviewLimit,
913		}
914		var matches []api.TrailReviewComment
915		for {
916			comments, hasMore, err := fetchTrailReviewComments(ctx, client, trailID, opts)
917			if err != nil {
918				return api.TrailReviewComment{}, err
919			}
920			for _, comment := range comments {
921				if comment.ID == commentID {
922					return comment, nil
923				}
924				if strings.HasPrefix(comment.ID, commentID) {
925					matches = append(matches, comment)
926				}
927			}
928			if !hasMore {
929				break
930			}
931			opts.Offset += opts.Limit
932		}
933		switch len(matches) {
934		case 0:
935			return api.TrailReviewComment{}, fmt.Errorf("no finding %q found", commentID)
936		case 1:
937			return matches[0], nil
938		default:
939			ids := make([]string, len(matches))
940			for i := range matches {
941				ids[i] = matches[i].ID
942			}
943			sort.Strings(ids)
944			return api.TrailReviewComment{}, fmt.Errorf("ambiguous finding %q (matches: %s)", commentID, strings.Join(ids, ", "))
945		}
946	}
