966	func fetchTrailReviewState(ctx context.Context, client *api.Client, trailID, reviewID string) (api.TrailReviewStateResponse, error) {
967		var merged api.TrailReviewStateResponse
968		cursor := ""
969		seenCursors := map[string]bool{}
970		for {
971			resp, err := client.Get(ctx, trailReviewStatePath(trailID, reviewID, cursor))
972			if err != nil {
973				return api.TrailReviewStateResponse{}, fmt.Errorf("get review state: %w", err)
974			}
975			var page api.TrailReviewStateResponse
976			decodeErr := func() error {
977				defer resp.Body.Close()
978				if err := checkTrailResponse(resp); err != nil {
979					return err
980				}
981				if err := api.DecodeJSON(resp, &page); err != nil {
982					return fmt.Errorf("decode review state: %w", err)
983				}
984				return nil
985			}()
986			if decodeErr != nil {
987				return api.TrailReviewStateResponse{}, decodeErr
988			}
989	
990			if cursor == "" {
991				merged = page
992			} else {
993				merged.Comments = append(merged.Comments, page.Comments...)
994				merged.NextCursor = page.NextCursor
995				merged.EventCursor = page.EventCursor
996			}
997	
998			if page.NextCursor == nil || strings.TrimSpace(*page.NextCursor) == "" {
999				merged.NextCursor = nil
1000				break
1001			}
1002			cursor = strings.TrimSpace(*page.NextCursor)
1003			if seenCursors[cursor] {
1004				return api.TrailReviewStateResponse{}, fmt.Errorf("review state pagination repeated cursor %q", cursor)
1005			}
1006			seenCursors[cursor] = true
1007		}
1008		return merged, nil
1009	}
