1037	func applyTrailReviewSuggestions(ctx context.Context, comment api.TrailReviewComment, checkOnly bool, w io.Writer) (int, error) {
1038		if len(comment.SuggestedChanges) == 0 {
1039			return 0, fmt.Errorf("finding %s has no suggested changes", comment.ID)
1040		}
1041		combinedPatch, supported, err := combinedSafeUnifiedDiffPatch(comment, w)
1042		if err != nil {
1043			return 0, err
1044		}
1045		if supported == 0 {
1046			return 0, fmt.Errorf("finding %s has no supported unified_diff suggested changes", comment.ID)
1047		}
1048		if err := runGitApply(ctx, combinedPatch, true); err != nil {
1049			return 0, fmt.Errorf("suggested changes for finding %s do not apply cleanly: %w", comment.ID, err)
1050		}
1051		if checkOnly {
1052			return supported, nil
1053		}
1054		if err := runGitApply(ctx, combinedPatch, false); err != nil {
1055			return 0, fmt.Errorf("apply suggested changes for finding %s: %w", comment.ID, err)
1056		}
1057		return supported, nil
1058	}
1059	
1060	func combinedSafeUnifiedDiffPatch(comment api.TrailReviewComment, w io.Writer) (string, int, error) {
1061		var combined strings.Builder
1062		supported := 0
1063		for _, change := range comment.SuggestedChanges {
1064			patch := strings.TrimSpace(stringPtrValue(change.Patch))
1065			if change.ChangeType != "unified_diff" || patch == "" {
1066				fmt.Fprintf(w, "Skipping suggested change %s (%s): only unified_diff patches are supported.\n", change.ID, change.ChangeType)
1067				continue
1068			}
1069			if err := validateUnifiedDiffPatchPaths(patch); err != nil {
1070				return "", 0, fmt.Errorf("suggested change %s has unsafe patch path: %w", change.ID, err)
1071			}
1072			if combined.Len() > 0 {
1073				combined.WriteByte('\n')
1074			}
1075			combined.WriteString(patch)
1076			combined.WriteByte('\n')
1077			supported++
1078		}
1079		return combined.String(), supported, nil
1080	}
1081	
1082	func validateUnifiedDiffPatchPaths(patchText string) error {
1083		scanner := bufio.NewScanner(strings.NewReader(patchText))
1084		scanner.Buffer(make([]byte, 0, 64*1024), 1<<20)
1085		for scanner.Scan() {
1086			line := scanner.Text()
1087			for _, p := range patchHeaderPaths(line) {
1088				if err := validatePatchPath(p); err != nil {
1089					return err
1090				}
1091			}
1092		}
1093		if err := scanner.Err(); err != nil {
1094			return fmt.Errorf("scan patch: %w", err)
1095		}
1096		return nil
1097	}
1098	
1099	func patchHeaderPaths(line string) []string {
1100		switch {
1101		case strings.HasPrefix(line, "diff --git "):
1102			fields := strings.Fields(strings.TrimPrefix(line, "diff --git "))
1103			if len(fields) >= 2 {
1104				return []string{fields[0], fields[1]}
1105			}
1106		case strings.HasPrefix(line, "--- ") || strings.HasPrefix(line, "+++ "):
1107			return []string{patchHeaderPath(line[4:])}
1108		case strings.HasPrefix(line, "rename from "):
1109			return []string{strings.TrimSpace(strings.TrimPrefix(line, "rename from "))}
1110		case strings.HasPrefix(line, "rename to "):
1111			return []string{strings.TrimSpace(strings.TrimPrefix(line, "rename to "))}
1112		case strings.HasPrefix(line, "copy from "):
1113			return []string{strings.TrimSpace(strings.TrimPrefix(line, "copy from "))}
1114		case strings.HasPrefix(line, "copy to "):
1115			return []string{strings.TrimSpace(strings.TrimPrefix(line, "copy to "))}
1116		}
1117		return nil
1118	}
1119	
1120	func patchHeaderPath(raw string) string {
1121		raw = strings.TrimSpace(raw)
1122		if beforeTab, _, ok := strings.Cut(raw, "\t"); ok {
1123			raw = beforeTab
1124		}
1125		return raw
1126	}
1127	
1128	func validatePatchPath(raw string) error {
1129		p := strings.TrimSpace(raw)
1130		if p == "" || p == "/dev/null" {
1131			return nil
1132		}
1133		if unquoted, err := strconv.Unquote(p); err == nil {
1134			p = unquoted
1135		}
1136		p = strings.TrimPrefix(p, "a/")
1137		p = strings.TrimPrefix(p, "b/")
1138		p = strings.ReplaceAll(p, "\\", "/")
1139		if strings.HasPrefix(p, "/") {
1140			return fmt.Errorf("absolute path %q is not allowed", raw)
1141		}
1142		clean := path.Clean(p)
1143		if clean == "." || clean == "" {
1144			return nil
1145		}
1146		if clean == ".." || strings.HasPrefix(clean, "../") {
1147			return fmt.Errorf("path %q escapes the repository", raw)
1148		}
1149		for _, part := range strings.Split(clean, "/") {
1150			// EqualFold guards case-insensitive filesystems (default macOS/Windows)
1151			// where ".GIT/config" would otherwise slip past an exact match.
1152			if strings.EqualFold(part, ".git") {
1153				return fmt.Errorf("path %q targets .git metadata", raw)
1154			}
1155		}
1156		return nil
1157	}
