1159	func runGitApply(ctx context.Context, patch string, checkOnly bool) error {
1160		root, err := paths.WorktreeRoot(ctx)
1161		if err != nil {
1162			return fmt.Errorf("resolve worktree root: %w", err)
1163		}
1164		args := []string{"-C", root, "apply"}
1165		if checkOnly {
1166			args = append(args, "--check")
1167		}
1168		cmd := exec.CommandContext(ctx, "git", args...)
1169		cmd.Stdin = bytes.NewBufferString(patch + "\n")
1170		out, err := cmd.CombinedOutput()
1171		if err != nil {
1172			msg := strings.TrimSpace(string(out))
1173			if msg != "" {
1174				return fmt.Errorf("git apply: %w: %s", err, msg)
1175			}
1176			return fmt.Errorf("git apply: %w", err)
1177		}
1178		return nil
1179	}
