package gitremote

import (
	"context"
	"os/exec"
	"testing"

	"github.com/entireio/cli/cmd/entire/cli/testutil"

	"github.com/stretchr/testify/assert"
	"github.com/stretchr/testify/require"
)

func TestParseURL(t *testing.T) {
	t.Parallel()

	tests := []struct {
		name     string
		url      string
		wantInfo *Info
		wantErr  bool
	}{
		{
			name:     "SSH SCP format",
			url:      "git@github.com:org/repo.git",
			wantInfo: &Info{Protocol: ProtocolSSH, Host: "github.com", Forge: "gh", Owner: "org", Repo: "repo"},
		},
		{
			name:     "SSH SCP without .git",
			url:      "git@github.com:org/repo",
			wantInfo: &Info{Protocol: ProtocolSSH, Host: "github.com", Forge: "gh", Owner: "org", Repo: "repo"},
		},
		{
			name:     "HTTPS format",
			url:      "https://github.com/org/repo.git",
			wantInfo: &Info{Protocol: ProtocolHTTPS, Host: "github.com", Forge: "gh", Owner: "org", Repo: "repo"},
		},
		{
			name:     "HTTPS without .git",
			url:      "https://github.com/org/repo",
			wantInfo: &Info{Protocol: ProtocolHTTPS, Host: "github.com", Forge: "gh", Owner: "org", Repo: "repo"},
		},
		{
			name:     "SSH protocol format",
			url:      "ssh://git@github.com/org/repo.git",
			wantInfo: &Info{Protocol: ProtocolSSH, Host: "github.com", Forge: "gh", Owner: "org", Repo: "repo"},
		},
		{
			name:     "HTTPS with non-standard port",
			url:      "https://git.example.com:8443/org/repo.git",
			wantInfo: &Info{Protocol: ProtocolHTTPS, Host: "git.example.com", Port: "8443", Owner: "org", Repo: "repo"},
		},
		{
			name:     "SSH protocol with non-standard port",
			url:      "ssh://git@git.example.com:2222/org/repo.git",
			wantInfo: &Info{Protocol: ProtocolSSH, Host: "git.example.com", Port: "2222", Owner: "org", Repo: "repo"},
		},
		{
			name:     "HTTPS standard port not appended",
			url:      "https://github.com/org/repo.git",
			wantInfo: &Info{Protocol: ProtocolHTTPS, Host: "github.com", Forge: "gh", Owner: "org", Repo: "repo"},
		},
		{
			name:     "entire:// gh prefix preserved as forge",
			url:      "entire://entirehost/gh/entireio/cli",
			wantInfo: &Info{Protocol: ProtocolEntire, Host: "entirehost", Forge: "gh", Owner: "entireio", Repo: "cli"},
		},
		{
			name:     "entire:// non-gh prefix preserved as forge",
			url:      "entire://abc/jk/myproject/repo",
			wantInfo: &Info{Protocol: ProtocolEntire, Host: "abc", Forge: "jk", Owner: "myproject", Repo: "repo"},
		},
		{
			name:     "entire:// regional host with gh forge",
			url:      "entire://aws-us-east-2.entire.io/gh/entirehq/entiredb",
			wantInfo: &Info{Protocol: ProtocolEntire, Host: "aws-us-east-2.entire.io", Forge: "gh", Owner: "entirehq", Repo: "entiredb"},
		},
		{
			name:     "entire:// with .git suffix",
			url:      "entire://entirehost/gh/entireio/cli.git",
			wantInfo: &Info{Protocol: ProtocolEntire, Host: "entirehost", Forge: "gh", Owner: "entireio", Repo: "cli"},
		},
		{
			name:     "unmapped host has empty forge",
			url:      "git@gitlab.com:org/repo.git",
			wantInfo: &Info{Protocol: ProtocolSSH, Host: "gitlab.com", Owner: "org", Repo: "repo"},
		},
		{
			name:    "empty string",
			url:     "",
			wantErr: true,
		},
		{
			name:    "no path",
			url:     "https://github.com",
			wantErr: true,
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			t.Parallel()
			info, err := ParseURL(tt.url)
			if tt.wantErr {
				assert.Error(t, err)
				return
			}
			require.NoError(t, err)
			assert.Equal(t, tt.wantInfo.Protocol, info.Protocol)
			assert.Equal(t, tt.wantInfo.Host, info.Host)
			assert.Equal(t, tt.wantInfo.Forge, info.Forge)
			assert.Equal(t, tt.wantInfo.Owner, info.Owner)
			assert.Equal(t, tt.wantInfo.Repo, info.Repo)
		})
	}
}

func TestExtractOwnerFromRemoteURL(t *testing.T) {
	t.Parallel()

1	// Package gitremote provides general-purpose git remote URL utilities:
2	// parsing, resolving, and redacting remote URLs. It has no dependency on
3	// checkpoint, strategy, or settings packages.
4	package gitremote
5	
6	import (
7		"context"
8		"fmt"
9		"net/url"
10		"os/exec"
11		"strings"
12	)
13	
14	const (
15		ProtocolSSH   = "ssh"
16		ProtocolHTTPS = "https"
17		// ProtocolEntire is the scheme of Entire's git remote helper (entire://).
18		// These URLs carry a forge/namespace prefix before owner/repo.
19		ProtocolEntire = "entire"
20	)
21	
22	// Info holds the parsed components of a git remote URL.
23	// Host is the hostname only (never includes a port). Port is empty unless the
24	// source URL specified an explicit non-default port. Callers that need the
25	// combined "host[:port]" form should use HostPort.
26	//
27	// Forge is the short identifier of the upstream forge ("gh", "et", ...) used
28	// by the Entire trails API. It is populated from the path prefix on entire://
29	// URLs (entire://host/<forge>/owner/repo) and from a hostname lookup on
30	// direct git URLs (github.com → "gh"). It is empty for direct git URLs to
31	// unrecognized hosts, and for entire:// URLs without a forge segment.
32	type Info struct {
33		Protocol string
34		Host     string
35		Port     string
36		Forge    string
37		Owner    string
38		Repo     string
39	}
40	
41	// hostToForge maps direct git hostnames to their forge identifier on the
42	// trails API. entire:// URLs carry the forge in the path instead and bypass
43	// this map.
44	var hostToForge = map[string]string{
45		"github.com": "gh",
46	}
47	
48	// forgeToHost is the reverse of hostToForge: it maps a forge identifier back to
49	// its canonical public host. Used to recover the real forge host from an
50	// entire:// remote, whose Host is the Entire cluster rather than the forge.
51	var forgeToHost = func() map[string]string {
52		m := make(map[string]string, len(hostToForge))
53		for host, forge := range hostToForge {
54			m[forge] = host
55		}
56		return m
57	}()
58	
59	// CanonicalHost returns the canonical public host of the upstream forge.
60	//
61	// For direct git URLs this is just Host. For entire:// remotes — whose Host is
62	// the Entire cluster (e.g. aws-us-east-2.entire.io) rather than the forge — it
63	// maps the forge prefix back to the forge's host (gh → github.com). Falls back
64	// to Host when the forge is unknown (e.g. a self-hosted GitHub Enterprise),
65	// preserving the only host we know for it.
66	func (i *Info) CanonicalHost() string {
67		if host, ok := forgeToHost[i.Forge]; ok {
68			return host
69		}
70		return i.Host
71	}
72	
73	// HostPort returns Host, or "Host:Port" when Port is non-empty.
74	func (i *Info) HostPort() string {
75		if i.Port == "" {
76			return i.Host
77		}
78		return i.Host + ":" + i.Port
79	}
80	
81	// GetRemoteURL returns the URL configured for the named git remote.
82	func GetRemoteURL(ctx context.Context, remoteName string) (string, error) {
83		return GetRemoteURLInDir(ctx, "", remoteName)
84	}
85	
86	// GetRemoteURLInDir returns the URL configured for the named git remote in dir.
87	func GetRemoteURLInDir(ctx context.Context, dir, remoteName string) (string, error) {
88		cmd := exec.CommandContext(ctx, "git", "remote", "get-url", remoteName)
89		if dir != "" {
90			cmd.Dir = dir
91		}
92		output, err := cmd.Output()
93		if err != nil {
94			return "", fmt.Errorf("remote %q not found", remoteName)
95		}
96		return strings.TrimSpace(string(output)), nil
97	}
