99	// ParseURL parses a git remote URL (SSH SCP-style or HTTPS) into its components.
100	func ParseURL(rawURL string) (*Info, error) {
101		rawURL = strings.TrimSpace(rawURL)
102	
103		if strings.Contains(rawURL, ":") && !strings.Contains(rawURL, "://") {
104			parts := strings.SplitN(rawURL, ":", 2)
105			if len(parts) != 2 {
106				return nil, fmt.Errorf("invalid SSH URL: %s", RedactURL(rawURL))
107			}
108	
109			hostPart := parts[0]
110			_, host, found := strings.Cut(hostPart, "@")
111			if !found {
112				host = hostPart
113			}
114	
115			pathPart := strings.TrimSuffix(parts[1], ".git")
116			owner, repo, err := splitOwnerRepo(pathPart)
117			if err != nil {
118				return nil, err
119			}
120	
121			return &Info{Protocol: ProtocolSSH, Host: host, Forge: hostToForge[host], Owner: owner, Repo: repo}, nil
122		}
123	
124		u, err := url.Parse(rawURL)
125		if err != nil {
126			return nil, fmt.Errorf("invalid URL: %s", RedactURL(rawURL))
127		}
128		if u.Scheme == "" {
129			return nil, fmt.Errorf("no protocol in URL: %s", RedactURL(rawURL))
130		}
131	
132		pathPart := strings.TrimPrefix(u.Path, "/")
133		forge := hostToForge[u.Hostname()]
134		if u.Scheme == ProtocolEntire {
135			// entire:// URLs encode the forge as the first path segment.
136			forge, pathPart = splitForgePrefix(pathPart)
137		}
138		owner, repo, err := splitOwnerRepo(pathPart)
139		if err != nil {
140			return nil, err
141		}
142	
143		return &Info{Protocol: u.Scheme, Host: u.Hostname(), Port: u.Port(), Forge: forge, Owner: owner, Repo: repo}, nil
144	}
145	
146	// splitForgePrefix returns the leading forge/namespace segment of an entire://
147	// URL path and the remainder (e.g. "gh/owner/repo" -> "gh", "owner/repo").
148	// Paths without a separator are returned with an empty forge.
149	func splitForgePrefix(path string) (forge, rest string) {
150		if forge, rest, found := strings.Cut(path, "/"); found {
151			return forge, rest
152		}
153		return "", path
154	}
155	
156	// RedactURL removes credentials and query parameters from a URL for safe logging.
157	// SCP-style SSH URLs (e.g., git@github.com:org/repo.git) are returned as-is
158	// since they contain no embedded credentials.
159	func RedactURL(rawURL string) string {
160		// SCP-style SSH: user@host:path — no credentials to redact.
161		if strings.Contains(rawURL, ":") && !strings.Contains(rawURL, "://") {
162			return rawURL
163		}
164	
165		u, err := url.Parse(rawURL)
166		if err != nil {
167			return "<unparseable>"
168		}
169		u.User = nil
170		u.RawQuery = ""
171		return u.Scheme + "://" + u.Host + u.Path
172	}
173	
174	// ExtractOwnerFromRemoteURL extracts the owner component from a git remote URL.
175	// Returns an empty string if the URL cannot be parsed.
176	func ExtractOwnerFromRemoteURL(rawURL string) string {
177		info, err := ParseURL(rawURL)
178		if err != nil {
179			return ""
180		}
181		return info.Owner
182	}
183	
184	// ResolveRemoteRepo returns the forge identifier, owner, and repo name for the
185	// given git remote. The forge is the short id used by the trails API ("gh",
186	// "et", ...); it is derived from the hostname for direct git URLs or from the
187	// path prefix on entire:// URLs. It is empty for unrecognized hosts.
188	// For example, git@github.com:org/my-repo.git returns ("gh", "org", "my-repo").
189	func ResolveRemoteRepo(ctx context.Context, remoteName string) (forge, owner, repo string, err error) {
190		rawURL, err := GetRemoteURL(ctx, remoteName)
191		if err != nil {
192			return "", "", "", fmt.Errorf("get remote URL for %q: %w", remoteName, err)
193		}
194		info, err := ParseURL(rawURL)
195		if err != nil {
196			return "", "", "", fmt.Errorf("parse remote URL: %w", err)
197		}
198		return info.Forge, info.Owner, info.Repo, nil
199	}
200	
201	func splitOwnerRepo(path string) (string, string, error) {
202		path = strings.TrimSuffix(path, ".git")
203		parts := strings.SplitN(path, "/", 2)
204		if len(parts) != 2 || parts[0] == "" || parts[1] == "" {
205			return "", "", fmt.Errorf("cannot parse owner/repo from path: %s", path)
206		}
207		return parts[0], parts[1], nil
208	}
