48	// trailsEnabledForRepo reports cached enablement for the current repo.
49	func trailsEnabledForRepo(ctx context.Context) bool {
50		return cachedTrailsEnablementForRepo(ctx, time.Now()) == trailEnablementCacheEnabled
51	}
