53	func cachedTrailsEnablementForRepo(ctx context.Context, now time.Time) trailEnablementCacheStatus {
54		scope, err := currentTrailEnablementScope(ctx)
55		if err != nil {
56			return trailEnablementCacheUnknown
57		}
58		return cachedTrailsEnablementForScope(ctx, scope, now)
59	}
