61	func cachedTrailsEnablementForScope(ctx context.Context, scope trailEnablementScope, now time.Time) trailEnablementCacheStatus {
62		prefs, err := settings.LoadClonePreferences(ctx)
63		if err != nil || prefs.TrailsEnabled == nil || prefs.TrailsEnabledCheckedAt == nil {
64			return trailEnablementCacheUnknown
65		}
66		if !trailEnablementCacheMatchesScope(prefs, scope) || trailEnablementCacheExpired(*prefs.TrailsEnabledCheckedAt, now) {
67			return trailEnablementCacheUnknown
68		}
69		if *prefs.TrailsEnabled {
70			return trailEnablementCacheEnabled
71		}
72		return trailEnablementCacheDisabled
73	}
