75	func trailEnablementCacheMatchesScope(prefs *settings.ClonePreferences, scope trailEnablementScope) bool {
76		return prefs.TrailsEnabledRepoKey == scope.RepoKey &&
77			prefs.TrailsEnabledAPIBase == scope.APIBase &&
78			prefs.TrailsEnabledAuthKey == scope.AuthKey
79	}
