81	func trailEnablementCacheExpired(checkedAt time.Time, now time.Time) bool {
82		if checkedAt.IsZero() {
83			return true
84		}
85		if now.Before(checkedAt) {
86			return true
87		}
88		return now.Sub(checkedAt) > trailEnablementCacheTTL
89	}
