91	func currentTrailEnablementScope(ctx context.Context) (trailEnablementScope, error) {
92		rawURL, err := gitremote.GetRemoteURL(ctx, "origin")
93		if err != nil {
94			return trailEnablementScope{}, fmt.Errorf("get origin remote: %w", err)
95		}
