97			return trailEnablementScope{}, errors.New("get origin remote: empty URL")
98		}
99		info, err := gitremote.ParseURL(rawURL)
100		if err != nil {
101			return trailEnablementScope{}, fmt.Errorf("parse origin remote: %w", err)
102		}
103		authKey, err := auth.LocalIdentityCacheKey()
104		if err != nil {
