141		path, err := trailEnablementScopeHintPath(ctx, sessionID)
142		if err != nil {
143			return trailEnablementScope{}, false, err
144		}
145		data, err := os.ReadFile(path) //nolint:gosec // path is derived from validated session ID
146		if err != nil {
